questionvariables.text:
/* Randomly select the magnitude of the sine value (6 variants: sin theta = -0.3 ... -0.8) */
k: 3+rand(6);

/* Given sine value */
given_value: -k/10;

/* Calculate the reference angle */
alpha_exact: float(asin(abs(given_value))*180/%pi);

/* Reference angle rounded to 1 decimal place */
ta0: round(alpha_exact*10)/10;

/* Calculate the two solutions */
theta1_exact: 180+alpha_exact;
theta2_exact: 360-alpha_exact;

/* Round solutions to 1 decimal place */
ta1: round(theta1_exact*10)/10;
ta2: round(theta2_exact*10)/10;

/* Decimal displays (dispdp always shows 1 decimal place, never a fraction) */
given_disp: dispdp(given_value, 1);
abs_disp: dispdp(abs(given_value), 1);
alpha_disp: dispdp(alpha_exact, 1);
t1_disp: dispdp(theta1_exact, 1);
t2_disp: dispdp(theta2_exact, 1);

/* Possible student mistakes */
alpha_rad: float(asin(abs(given_value)));       /* calculator in radian mode */
wq1: alpha_exact;                               /* solutions in Quadrants I and II (sign ignored) */
wq2: 180-alpha_exact;

feedbackvariables.text:
/* The two solutions may be entered in either order; allow 0.06 for rounding to 1 decimal place */
lo : min(ans1, ans2);
hi : max(ans1, ans2);
c1 : is(abs(lo - theta1_exact) <= 0.06);
c2 : is(abs(hi - theta2_exact) <= 0.06);
both : is(c1 and c2);
onlyone : is(c1 or c2);
wrongquads : is(abs(lo - wq1) <= 0.06 and abs(hi - wq2) <= 0.06);
